<?php if(!defined('ABSPATH')){exit;} get_header(); ?><main id="main"><div class="container page-space"><?php while(have_posts()):the_post(); ?><nav class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">خانه</a><span>/</span><a href="<?php echo esc_url(mht_url('blog.html')); ?>">مجله هشتگ</a></nav><header class="article-header"><span class="overline">راهنمای خرید · مجله هشتگ</span><h1><?php the_title(); ?></h1><p><?php echo esc_html(get_the_date()); ?></p></header><?php the_post_thumbnail('full',['class'=>'article-hero']); ?><div class="prose"><?php the_content();wp_link_pages(); ?></div><?php if(comments_open()||get_comments_number()){comments_template();}endwhile; ?><section class="section"><div class="section-heading"><h2>بیشتر بخوانید</h2></div><div class="blog-grid"><?php foreach(get_posts(['numberposts'=>3,'exclude'=>get_the_ID()]) as $article){mht_post_card($article);} ?></div></section></div></main><?php get_footer(); ?>
